const assert=require("node:assert/strict");
const fs=require("node:fs");
const page=fs.readFileSync("src/app/page.tsx","utf8");
const mobile=fs.readFileSync("src/app/components/ziiply/cards/ZiiplyMobileCartCard.tsx","utf8");
const eligibility=page.match(/function isComparisonEligibleV797\(item: CartItem\) \{([\s\S]*?)\n  \}/);
assert.ok(eligibility,"comparison eligibility exists");
assert.match(eligibility[1],/if \(String\(item\.source \|\| ""\)\.toLowerCase\(\) === "offer"\) return false;/);
assert.doesNotMatch(page,/isComparableWeightOfferV797/,"€/kg offer comparison exception removed");
assert.match(page,/const comparableCartV730 = cart\.filter\(isComparisonEligibleV797\);/);
assert.match(page,/setCartCompareNotice\("Tarjoustuotteita ei halpuuteta uudelleen/);
assert.match(page,/showCartToast\("Tarjoustuotteita ei halpuuteta uudelleen/);
assert.match(mobile,/if \(isPendingWeightPriceV794\(item\)\) return 0;/);
console.log("PASS all Gösta offers excluded from comparison, offer-only notice surfaced, pending weight excluded from receipt total");
